private fun decodeCars(items: List<DittoQueryResultItem>): List<Car> =
    items.mapNotNull { item ->
        runCatching { json.decodeFromString<Car>(item.jsonString()) }
            .onFailure { Log.w("Cars", "Skipping malformed car doc", it) }
            .getOrNull()
    }

// Screen 1 — list ViewModel
class CarListViewModel(ditto: Ditto) : ViewModel() {
    val cars: StateFlow<List<Car>> =
        ditto.store.observe("SELECT * FROM cars") { result ->
            withContext(Dispatchers.IO) { decodeCars(result.items) } // result still open here
        }.stateIn(viewModelScope, SharingStarted.WhileSubscribed(5_000), emptyList())
}

// Screen 2 — detail ViewModel using registerObserver
class CarDetailViewModel(ditto: Ditto, carId: String) : ViewModel() {
    private val _car = MutableStateFlow<Car?>(null)   // plain data, never DittoQueryResult/items
    val car: StateFlow<Car?> = _car

    private val observer = ditto.store.registerObserver(
        "SELECT * FROM cars WHERE _id = :id",
        mapOf("id" to carId),
    ) { result ->
        try {
            val decoded = withContext(Dispatchers.IO) { decodeCars(result.items).firstOrNull() }
            _car.value = decoded
        } catch (e: CancellationException) {
            throw e
        } catch (e: Exception) {
            Log.e("CarDetail", "Observer handler failed", e) // never let it escape: SDK would close the observer
        }
    }

    override fun onCleared() {
        observer.close()
    }
}
```

Compose collects both with `collectAsStateWithLifecycle()`. When `viewModelScope` is cancelled, the Screen 1 observer closes automatically. Screen 2 needs the explicit `observer.close()`.

